/**
 * Generate Slack app manifests (dev + prod) for Cursor-managed provision.
 *
 * Always Socket Mode. No Events Request URL. Humans do not paste these
 * at api.slack.com; `slack create` sends them through the dashboard wizard.
 *
 * Mirrored by backend/server/src/agentServe/agentServeSlackManifest.ts (the
 * backend cannot import this published package); keep the twins in lockstep.
 */
import { CHAT_WRITE_CUSTOMIZE_SCOPE } from "../../internal/slack-bot-scopes.js";
/**
 * Dashboard tab root: Slack's app-settings banner, and the only OAuth
 * redirect URI we register. AAA request-approval (`oauth_authorize_url`)
 * 400s with redirect_uri mismatch unless a URI is registered. This is
 * not an install callback. `apps.managedInstall` still installs.
 */
export const SLACK_EXTERNAL_APP_MANAGEMENT_URL = "https://cursor.com/dashboard/deployed-agents";
/**
 * Every scope the shared Slack channel uses, requested by every app that
 * names no {@link SlackManifestOptions.botScopes}. A new scope here forces a
 * reinstall. Nothing that workspace policies commonly refuse
 * (`chat:write.public`, `channels:join`) is here.
 */
const BOT_SCOPES = [
    "app_mentions:read",
    "assistant:write",
    "channels:history",
    // Resolve and verify watched channels (`#name` allowlists, `slack doctor`).
    "channels:read",
    "chat:write",
    "files:read",
    "files:write",
    "groups:history",
    "groups:read",
    "im:history",
    "im:read",
    "im:write",
    "mpim:history",
    // `reaction_added` wakes (`onReactionAdded`).
    "reactions:read",
    // Emoji acknowledgements (e.g. an agent reacting 👀 when it locks onto
    // a watched-channel post before investigating).
    "reactions:write",
    // Resolve user groups and people by email in agent tools.
    "usergroups:read",
    "users:read",
    "users:read.email",
];
/** Every event the channel dispatches on. */
const BOT_EVENTS = [
    "app_mention",
    "message.im",
    // agent_view DMs: Slack no longer fires assistant_thread_started.
    "app_home_opened",
    "message.channels",
    "message.groups",
    "reaction_added",
    // Slack shows the native Stop control only when the app subscribes to this event.
    "agent_session_stopped",
];
/** Slack's display_information.description bound. */
const MAX_DESCRIPTION_LENGTH = 140;
const DESCRIPTION_SUFFIX = " — an AI agent built with Cursor";
/** Marketplace review rejects managed apps whose manifest omits a description. */
function defaultDescription(name) {
    const room = MAX_DESCRIPTION_LENGTH - DESCRIPTION_SUFFIX.length;
    // Code points, so truncation cannot halve a surrogate pair.
    return `${Array.from(name).slice(0, room).join("")}${DESCRIPTION_SUFFIX}`;
}
function appSlug(name) {
    const base = name
        .toLowerCase()
        .replace(/[^a-zA-Z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 32);
    return base.length > 0 ? base : "agent";
}
function isBennyApp(name) {
    return appSlug(name) === "benny";
}
function toBotDisplayName(name, env) {
    const fallback = appSlug(name);
    // The Cursor Automations Benny already owns @benny in the Anysphere
    // workspace, so the agent-serve Benny app must use @benny-dev in both
    // envs (not only the usual -dev suffix on the dev profile).
    if (fallback === "benny") {
        return "benny-dev";
    }
    return env === "dev" ? `${fallback}-dev`.slice(0, 35) : fallback;
}
/**
 * Build a Slack app manifest suitable for Create from Manifest.
 */
export function buildSlackManifest(options) {
    const env = options.env;
    const benny = isBennyApp(options.name);
    // Benny's app title matches its handle so the Install App UI shows
    // benny-dev (not "benny (dev)" / "Benny").
    const displayName = benny ? "benny-dev" : env === "dev" ? `${options.name} (dev)` : options.name;
    const botName = options.botDisplayName ?? toBotDisplayName(options.name, env);
    const description = options.description ?? defaultDescription(options.name);
    const agentDescription = options.agentDescription ?? description;
    const includeAgentView = options.assistant !== false;
    const botScopes = [
        ...new Set(options.botScopes ??
            (includeAgentView ? BOT_SCOPES : BOT_SCOPES.filter((scope) => scope !== "assistant:write"))),
    ];
    if (options.chatWriteCustomize === true && !botScopes.includes(CHAT_WRITE_CUSTOMIZE_SCOPE)) {
        // After chat:write, else last: the backend foldChatWriteCustomize placement.
        const at = botScopes.indexOf("chat:write");
        botScopes.splice(at === -1 ? botScopes.length : at + 1, 0, CHAT_WRITE_CUSTOMIZE_SCOPE);
    }
    const suggested = options.suggestedPrompts !== undefined ? options.suggestedPrompts : [];
    return {
        display_information: {
            name: displayName,
            description,
        },
        features: {
            bot_user: {
                display_name: botName,
                always_online: true,
            },
            app_home: {
                home_tab_enabled: false,
                messages_tab_enabled: true,
                messages_tab_read_only_enabled: false,
            },
            agent_view: includeAgentView
                ? {
                    agent_description: agentDescription,
                    suggested_prompts: suggested,
                }
                : undefined,
        },
        oauth_config: {
            scopes: {
                bot: botScopes,
            },
            redirect_urls: options.managedByCursor === false ? undefined : [SLACK_EXTERNAL_APP_MANAGEMENT_URL],
        },
        settings: {
            event_subscriptions: {
                bot_events: [...BOT_EVENTS],
            },
            interactivity: {
                is_enabled: true,
            },
            // Benny installs org-wide in the Cursor FE & ADM workspace.
            org_deploy_enabled: benny,
            // Always Socket Mode — agent-serve has no Events Request URL path.
            // (Do not set false even if Slack's empty-app stub defaults to off.)
            socket_mode_enabled: true,
            token_rotation_enabled: false,
            is_mcp_enabled: false,
            ...(options.managedByCursor === false
                ? {}
                : {
                    managed_app_settings: {
                        is_install_from_slack_disabled: true,
                        external_app_management_url: SLACK_EXTERNAL_APP_MANAGEMENT_URL,
                    },
                }),
        },
    };
}
export function buildSlackManifestPair(options) {
    return {
        dev: buildSlackManifest({ ...options, env: "dev" }),
        prod: buildSlackManifest({ ...options, env: "prod" }),
    };
}
/** Manifest filenames written under `.slack/`. */
export function slackManifestFileEntries(pair, env = "both") {
    const files = [];
    if (env === "dev" || env === "both") {
        files.push({
            name: "manifest.dev.json",
            contents: `${JSON.stringify(pair.dev, null, 2)}\n`,
        });
    }
    if (env === "prod" || env === "both") {
        files.push({
            name: "manifest.prod.json",
            contents: `${JSON.stringify(pair.prod, null, 2)}\n`,
        });
    }
    return files;
}
